@font-face{font-family:Roboto;src:url('/frontend/fonts/roboto-400.77670407a009.woff2') format('woff2');font-style:normal;font-weight:100 900;font-display:swap}@font-face{font-family:'Playfair Display';src:url('/frontend/fonts/playfair-display-400.7546c242e6ac.woff2') format('woff2');font-style:normal;font-weight:400 900;font-display:swap}body{font-family:Roboto,Arial,sans-serif;font-size:15px;line-height:1.7;color:#26324a}h1{font-family:Roboto,Arial,sans-serif;font-size:25px;line-height:1.35;color:#10265e}h2{font-size:22px;line-height:1.4;color:#18377a}h3{font-size:18px;line-height:1.5}p,li{font-size:15px;line-height:1.7}footer{font-family:Roboto,Arial,sans-serif}.banner{background:#edf3ff}.nav-bar{background:#10265e}input,select,textarea{font-family:Roboto,Arial,sans-serif;font-size:15px;border:1px solid #ccd7e7}table{max-width:100%;font-size:13px}.rd-details-container{padding:25px 15px;background:#f3f6fc}amp-accordion section>h2{padding:16px;background:#eef3fb;border:1px solid #dce5f2}@media(max-width:600px){h1{font-size:21px}h2{font-size:20px}p,li{font-size:14px}}
